<?php
declare(strict_types=1);namespace Atlas\Platform\Workflows\Rest;use Atlas\Platform\Organizations\Services\CurrentOrganizationResolver;use Atlas\Platform\Workflows\Services\WorkflowReader;use WP_Error;use WP_REST_Request;use WP_REST_Response;final class WorkflowController{public function __construct(private WorkflowReader$reader,private CurrentOrganizationResolver$organizations){}public function permission():bool{return is_user_logged_in()&&current_user_can('atlas_access');}public function show(WP_REST_Request$r):WP_REST_Response|WP_Error{$id=strtolower(sanitize_text_field((string)$r->get_param('id')));if(preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/',$id)!==1){return new WP_Error('atlas_workflow_invalid_id',__('The workflow identifier is invalid.','atlas-platform'),['status'=>400]);}$org=$this->organizations->resolveForUser(get_current_user_id());$workflow=$this->reader->find($id,$org?->id);return$workflow===null?new WP_Error('atlas_workflow_not_found',__('The workflow was not found or is not accessible.','atlas-platform'),['status'=>404]):new WP_REST_Response(['workflow'=>$workflow->toArray()],200);}}
